pattern.considerations:

// Arquivo em árabe deve ter marcação RTL
// messages/ar/common.json
{
  "navigation": {
    "home": "الرئيسية",
    "screening": "الفحص الدوري",
    "diseases": "الأمراض",
    "medications": "الأدوية"
  },
  "directions": {
    "next": "التالي", // Aparece à esquerda em RTL
    "previous": "السابق" // Aparece à direita em RTL
  }
}

// CSS para RTL
[dir="rtl"] {
  text-align: right;
  direction: rtl;
}

pattern.examples:

// next-intl plural handling
{
  "results": "{count, plural, =0 {Nenhum resultado} one {# resultado} other {# resultados}}"
}

// English
{
  "results": "{count, plural, =0 {No results} one {# result} other {# results}}"
}

// Arabic (complex plural rules)
{
  "results": "{count, plural, =0 {لا نتائج} one {نتيجة واحدة} two {نتيجتان} few {# نتائج} many {# نتيجة} other {# نتيجة}}"
}
